INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,status,url_slug,created_at,updated_at) VALUES
('disciple-the-menagerie','Disciple','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"disciple-the-menagerie","name":"Disciple","team":"townsfolk","ability":"On your first night, you learn if either of the Evangelist''s living neighbours are evil.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Thank you for being the shepherd that ushers me unto salvation.","lede":"The Disciple is created by the Evangelist, and helps them know their neighbours.","howToRun":["When building scripts, remember to include the Evangelist as an extra character (ie. 14 total Townsfolk as opposed to the normal 13)."],"tips":["Congratulations on being selected by the Evangelist! In your new role, you learn whether the Evangelist neighbours a living evil player. While that''s all you learn, it is nonetheless powerful, and might give you a little extra information in addition to what you may have already gleaned. Additionally, if the Evangelist spoke with you during the day noting that they might be choosing you at night, you can be inclined to trust their claim, since you have some level of mechanical confirmation to speak to. Go, child, and spread the good word."],"bluffing":["Congratulations on being selected by the Evangelist! What a shame they''ve picked an evil player who has no intention of turning, though.","Unless...","As the Disciple, whether good or evil, remember that you do register as a Townsfolk, so if you''re a spent Minion, such as the Baron or Widow with a dead poisoned player, you may want to accept the Evangelist''s kind offer to mess with other information. A Ravenkeeper with suspicion towards you will see you as the Disciple; a Balloonist will receive you in their pings as a Townsfolk; and so much more.","Whether you accept the Evangelist''s offer or not, give them information that best frames the world you''re trying to build: clear their neighbours if evil, or frame them if good. It''s totally up to you!"],"fighting":[],"examples":["Sage is the Evangelist who selects Dan at night. Dan is a spent Chef, and so they accept Sage''s offer, turning into the Disciple. Dan learns that there are no evil players beside him.","Ben, the Baron, has been selected by the Evangelist at night. They accept. The next day, they nominate the Evangelist''s good neighbour, but do not trigger the Town Crier''s ability."],"firstNight":0,"firstNightReminder":"","otherNight":57.5,"otherNightReminder":"Wake the Disciple: nod or shake your head.","reminders":[],"setup":false,"special":[{"name":"bag-disabled","type":"selection"}],"jinxes":[{"name":"Drunk","align":"good","text":"If the Drunk becomes the Disciple, they remain drunk.","id":"drunk"},{"name":"Stowaway","align":"good","text":"If the Stowaway becomes the Disciple, they are drunk.","slug":"stowaway-the-menagerie"},{"name":"Scarlet Woman","align":"good","text":"If a living Demon becomes the Disciple and there are 5 or more players alive, this triggers the Scarlet Woman''s ability. (Travellers don''t count.).","id":"scarletwoman"}],"image":"https://menagerie.towerrangers.net/images/disg.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/dise.png"}','published','the-menagerie/disciple',datetime('now'),datetime('now')),
('evangelist','Evangelist','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"evangelist","name":"Evangelist","team":"townsfolk","ability":"Once per game*, at night, select a player. If they agree, they become the Disciple.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Lost! Lost! Lost! Better a whole world on fire than a soul lost!","lede":"The Evangelist can make another player their Disciple, but doesn''t know their true intentions.","howToRun":["When building scripts, remember to include the Disciple as an extra character (ie. 14 total Townsfolk as opposed to the normal 13)."],"tips":["You are, more or less, a good Pit Hag who can turn a player into a trusted Disciple. But finding a suitable target for this ability is tricky, since you never learn if the player you''ve selected actually accepted your ability. Are they really the Disciple with a good read on your living neighbours? Or are they a Minion who declined, but is bluffing the information anyway? You may never know, but finding roles that can confirm players'' identities can help greatly, so work with them to ensure your Disciple is on the level. If so, you can help create a chain of confirmation that can potentially lead to a solve."],"bluffing":["Instead of creating confirmation among good players, why not create a dynamic duo on the evil team? It''s risky, but with information on your side, you can pair up with a fellow evil player to clear players on either side, creating trust, or close the walls in on an already framed evil player. Just know that as the Evangelist, you and your Disciple are both prime targets for suspicion if those players are cleared by other means.","Alternatively, if you have a Pit Hag in play, you may want to consider turning a spent Minion into the Evangelist to have them attempt to convert someone else! Doing so will give some level of mechanical confirmation in the eyes of that player, and could help sway voting later on."],"fighting":[],"examples":["Sage is the Evangelist who selects Dan at night. Dan is a spent Chef, and so they accept Sage''s offer, turning into the Disciple. Dan learns that there are no evil players neighbouring Sage.","Lachlan is the Evangelist who tells Fred, a Minion, that they will be selecting them to become a Disciple at night. Fred declines Lachlan''s ability, but claims that they accepted it, learning that Lachlan''s living neighbours - the Demon and a good player - are both good."],"firstNight":0,"firstNightReminder":"","otherNight":57.5,"otherNightReminder":"Wake the Evangelist and ask them if they want to use their ability. If they do, wake the player they choose and ask them if they wish to become the Disciple.","reminders":["No Ability","Chosen"],"setup":false,"image":"https://menagerie.towerrangers.net/images/evag.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/evae.png"}','published','the-menagerie/evangelist',datetime('now'),datetime('now')),
('gatekeeper-the-menagerie','Gatekeeper','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"gatekeeper-the-menagerie","name":"Gatekeeper","team":"townsfolk","ability":"Each night*, if you nominated today, learn one not-in-play character. [+0 or +1 Outsider]","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Halt! Who goes there?","lede":"The Gatekeeper learns characters who aren''t in the game, but has to risk exposing themselves to do so.","howToRun":["The Gatekeeper is strongest in larger games: consider reserving their use for games with around 9-13 players: any less, and the Gatekeeper’s information is difficult to work with, and with more, there is a likelihood that the Gatekeeper almost immediately begins to receive Demon bluffs. Remember that not-in-play Outsiders, Minions and Demons are also valid to provide, so consider giving these to the Gatekeeper, especially if good is struggling."],"tips":["In order to gain information at night, you have to nominate during the day: doing so may potentially signal to evil that you are the Gatekeeper, so it may be worth being a little sparing with your accusations. Either way, your information can be extremely helpful to your team, as it may expose bluffs, provide information about what evil characters are in play, and in some instances, may be game-solving!"],"bluffing":["Nominate, nominate, nominate. You know what Minions and Demons are not-in-play, so consider either providing true information to gain trust, or spreading misinformation to guide good down the wrong path. Given that your “ability” is gated behind nominations, you can pull double duty and cast aspersions against good Townsfolk to potentially get them off the board at the same time, but remember that if town is inclined to question your information, any or all of it may be reverse engineered into helpful information for town."],"fighting":[],"examples":["Annie is the Gatekeeper. They nominate a player during the day, and at night, learn that the Seamstress - a demon bluff - is not in play.","Julia is an evil player bluffing as the Gatekeeper. They nominate, and tell town the next day that the Baron is not in play. They know a Drunk is in play, and can cast doubt on the other Outsider claim."],"firstNight":0,"firstNightReminder":"","otherNight":57.5,"otherNightReminder":"If the Gatekeeper nominated today, the Gatekeeper learns a not-in-play character.","reminders":["Nominated"],"setup":true,"image":"https://menagerie.towerrangers.net/images/gatg.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/gate.png"}','published','the-menagerie/gatekeeper',datetime('now'),datetime('now')),
('guardian-the-menagerie','Guardian','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"guardian-the-menagerie","name":"Guardian","team":"townsfolk","ability":"Each night, learn a player. From night 2, pick a player (not yourself). If the Demon chooses them at night, learn whether the Demon is a known player.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Ahakoa he iti, he pounamu.","lede":"The Guardian learns who the Demon could be, if they can predict the Demon''s movements.","howToRun":["Consider when you give the Demon to the Guardian, as this will impact the integrity of the Guardian''s information."],"tips":["You don''t have access to any valuable information unless you are able to successfully pin down who the Demon targets during the night: so learning roles about town is essential to your success. If you can figure out where the high-value kills might reside, you can lean into them to hopefully catch the Demon killing them. From there, whether you receive a yes or a no, you''ve whittled down the list of Demon candidates. You can do this multiple times per game, meaning you''ll be able to separate players into clusters of players who definitely aren''t, or plausibly are the Demon, which is incredibly powerful information to have."],"bluffing":["Fabricating information that sounds plausible is key to bluffing as the Guardian. Not only are you able to frame certain players as the Demon, but you can \"miss\" the Demon for multiple nights and get a yes - finally - between a large number of players, rendering your information plausibly true, but difficult to pin down. Moreover, you can help shape a world where a Monk protected a player, or a Mayor bounced, since the Guardian''s ability only asks that you choose the same player that the Demon chose, even if they didn''t die. So you can help sell bluffs at the same time as spreading misinformation!"],"fighting":[],"examples":["Dwayne is the Guardian, who correctly picks the player the Demon chooses on Night 4 and Night 6. Dwayne learns that the Demon is not among the players that Dwayne learned up until Night 4, but learns that the Demon is among the players learned on Night 6: as such, the Demon is one of two players.","Colin is a Minion bluffing as the Guardian. They claim, on Night 5, to have finally received a yes on a night where noone died. The Demon, bluffing Monk, sinks a kill on that night."],"firstNight":47,"firstNightReminder":"Show the Guardian one player. Mark that player with the *Known* token .","otherNight":57.5,"otherNightReminder":"Show the Guardian one player. Mark that player with the *Known* token . Ask the Guardian to pick a player. If that player was chosen by the Demon, nod or shake your head.","reminders":["Known","Known","Known","Known","Known","Known","Known","Known","Known","Known","Known","Known","Known","Learns Tonight"],"setup":false,"image":"https://menagerie.towerrangers.net/images/guag.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/guae.png"}','published','the-menagerie/guardian',datetime('now'),datetime('now')),
('houndmaster','Houndmaster','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"houndmaster","name":"Houndmaster","team":"townsfolk","ability":"If you die at night, pick a player: you learn the number of steps from them to the nearest evil player.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"A hunter without a hound is an orchestra without a conductor.","lede":"The Houndmaster can sniff out where evil might reside upon their own death.","howToRun":["Remember that dead players also count for \"steps\" - don''t skip!"],"tips":["As would be the case with any \"demon-bane\" roles, consider claiming strong information roles to bait a kill at night. Unlike a Clockmaker that must track a Demon to its nearest Minion, the Houndmaster gets to select where the ping originates, and additionally, the Houndmaster may receive a zero, indicating that they''ve sniped an evil directly - which is great information to have. Other than that, you''ll need to play the waiting game, and consider finding a role swap if possible!"],"bluffing":["The Houndmaster is a fantastic bluff for a Minion killed by a Vigormortis, or a Demon that can \"jump\" like the Imp, Fang Gu or Hypnox. Steering town towards a false ping is a great way to waste time, and kill off powerful roles by implicating them as evil. Be cautious about confirmation roles, and enjoy watching the good team eat themselves up in light of your death."],"fighting":[],"examples":["Criss is the Houndmaster who dies to the Harlot''s ability. Criss chooses Finn, the Oracle, and learns a 2.","Angel is the Imp who passes to their Gerrymanderer in the night. Upon waking, Angel claims that they chose Sanjay, and received a 3, pointing to the Oracle and the Fortune Teller either side."],"firstNight":0,"firstNightReminder":"","otherNight":57.5,"otherNightReminder":"If the Houndmaster dies at night, wake them and ask them to pick a player. Show them a number.","reminders":[],"setup":false,"image":"https://menagerie.towerrangers.net/images/houg.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/houe.png"}','published','the-menagerie/houndmaster',datetime('now'),datetime('now')),
('lost-lover','Lost Lover','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"lost-lover","name":"Lost Lover","team":"townsfolk","ability":"Once per game, at night, choose a living player (not yourself): if either chooses the Lost Lover, 1 learns the in-play Demon; the other, in-play Minions. If either guesses wrong, both get false info. [+Lost Lover]","creator":"Goodpart","appearsIn":"The Menagerie","quote":"And she as much in love, her means much less / To meet her new belovèd anywhere / But passion lends them power, time means, to meet / Temp’ring extremities with extreme sweet.","lede":"The Lost Lovers learn what evil they are fighting, if they can find each other in time.","howToRun":["Remember to mark one Lost Lover with the “First” token to ensure that you contact the same player first each night. If the good team is struggling at the moment a choice is made, and the choice is incorrect, you may consider giving partially correct information; either a correct Demon, a handful of correct Minions, or some combination inbetween."],"tips":["If you are sober and in play, you know there is another Lost Lover out there waiting for you - so find them. They may also be looking for their other half, of course, and so time is against you to seek out the right player and guess them in the night, since if either party makes their guess, that counts for both Lost Lovers. Consider waiting until there is some form of confirmation around your, or your potential partner’s identity before making a guess, and defend them as you would yourself to ensure they can be chosen at night! Your information, if true, is extremely powerful, and so you will be a priority target for the evil team."],"bluffing":["This one is pretty simple: if you feel there is another Lost Lover in the game, goad them into choosing you at night to extract incorrect information. Alternatively, form a pact with a fellow evil player to “guess” them later in the game, and advocate that town keep them safe just in case. Either way, hedging your bets by claiming to be a Lost Lover can be extremely useful, as it will cause other Lost Lovers in the game to second guess their choice at night."],"fighting":[],"examples":["Dan and Ann are Lost Lovers. On Night 3, Dan uses their ability and selects Ann. Dan learns that there is a Fang Gu in play. Ann wakes to learn that a Witch and a Marionette are in play.","Alex is the Vigormortis bluffing as a Lost Lover. They coax Kevin - a real Lost Lover - into selecting them at night. Kevin learns that a Xaan is in play. Maya, the other real Lost Lover, wakes to learn that an Imp is in play."],"firstNight":46,"firstNightReminder":"Wake the Lost Lover marked ''First''. Ask them if they wish to use their ability. If they select the other Lost Lover, they receive the info noted in the Lost Lover''s ability, or false info if not. Wake the other and do the same if the first Lost Lover declines.","otherNight":57.5,"otherNightReminder":"Wake the Lost Lover marked ''First''. Ask them if they wish to use their ability. If they select the other Lost Lover, they receive the info noted in the Lost Lover''s ability, or false info if not. Wake the other and do the same if the first Lost Lover declines.","reminders":["First","Wrong Info","Wrong Info","Lost Love Found"],"setup":true,"special":[{"type":"selection","name":"bag-duplicate"}],"jinxes":[{"name":"Philosopher","align":"good","text":"If the Philosopher gains the Lost Lover ability, one Lost Lover is drunk, not both. If no other Lost Lover is in play, learn either an in-play Demon, or one in-play Minion.","id":"philosopher"},{"name":"Pixie","align":"good","text":"If the Pixie is mad as the Lost Lover, they gain the ability if one Lost Lover dies.","id":"pixie"}],"image":"https://menagerie.towerrangers.net/images/losg.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/lose.png"}','published','the-menagerie/lost-lover',datetime('now'),datetime('now')),
('martyr-the-menagerie','Martyr','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"martyr-the-menagerie","name":"Martyr","team":"townsfolk","ability":"Once per game, at night*, you may learn the character of a player chosen by the Demon tonight, and die in their place.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"The only thing that lingers longer than the blood of a martyr is the guilt of the one who survives.","lede":"The Martyr learns who would otherwise die, at the cost of their own life.","howToRun":["Given that if sober, the Martyr''s effect must happen - just make sure you give a character, and not a player."],"tips":["Your ability is fairly straightforward, so your role boils down to when you choose to use it. If a powerful Townsfolk outs on any given day, consider using your ability to see if their claim stacks up. Or perhaps, if you see a Demon-bane role like the Ravenkeeper, you may want to announce what you saw to guide the Demon back to the player they chose. Better yet, seeing a Demon like the Imp or Hypnox means that the Demon tried to pass - so capitalise on any players with heavy suspicion on them to get them out before they''re able to jump! As an additional benefit, if you believe it to be a Fang Gu game, you may well protect an Outsider from being jumped, potentially removing them as an intended target."],"bluffing":["Bluffing as the Martyr isn''t dissimilar to bluffing as the Ravenkeeper or something like it. However, the specificity of your information is lessened, meaning you only need to confirm a role in play, rather than a specific role a character is claiming. That said, you can consider using your Martyr bluff to confirm the existence of a Demon bluff - but beware: if you do this, it''s likely that town will expect that player to die later, so ensure you have an escape hatch."],"fighting":[],"examples":["Lochie is the Martyr. He chooses to use his ability on Night 3, and learns Undertaker. Lochie dies the next morning.","Jules is the Imp who star passes on Night 4. They wake in the morning, dead, and claim to be the Martyr that saw the Alchemist, implying they were targeted in the night."],"firstNight":0,"firstNightReminder":"","otherNight":34,"otherNightReminder":"The Martyr may choose to use their ability. If they do, mark the Martyr as Dead. The Martyr learns the character marked Dead by the Demon.","reminders":["Dead","Learns"],"setup":false,"jinxes":[{"name":"Innkeeper","align":"good","text":"If the Martyr is protected by the Innkeeper on the night they use their ability, the Martyr does not die, but learns arbitrary information.","id":"innkeeper"}],"image":"https://menagerie.towerrangers.net/images/marg.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/mare.png"}','published','the-menagerie/martyr',datetime('now'),datetime('now')),
('mime-the-menagerie','Mime','townsfolk','Goodpart',NULL,NULL,'The Menagerie','{"slug":"mime-the-menagerie","name":"Mime","team":"townsfolk","ability":"If you are ''mad'' as a good character today, learn if it is in play the next night.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"...! ...? ...?! ...! ...!","lede":"The Mime''s performances lead them to learn what is in play, and what is not.","howToRun":["Madness in this context should work similarly to the Pixie. While players may discern the player is in fact the Mime, so long as the Mime is continuing to adhere to madness, they should not be punished."],"tips":["Stick to the act! You will inevitably cause double claims and sow distrust in town, but your performances are for a greater good. You may consider dropping the act at some point to let players know what you are, but know that you won''t receive any information that night. It''s a small sacrifice, and potentially worth it if it means gaining the trust of your peers - but it may also attract the attention of the evil team."],"bluffing":["Not only is bluffing as the Mime great for planting the seeds of distrust by creating double claims, but the \"information\" you share afterwards can even further harm town. Be judicious with what you claim isn''t in play, as only so many roles cannot exist. Ensure the roles you claim not to exist are roles you want out of town, or are attached to players who have particular suspicions."],"fighting":[],"examples":["Chris is the Mime who decides to pretend to be the Monk. They claim that role the following day, and learn that night that the Monk is in play.","Pauline is the Baron who is bluffing as the Mime. They pretend to be the Soldier, which they know to be in play, and claim later that the Soldier is not in play."],"firstNight":0,"firstNightReminder":"","otherNight":64,"otherNightReminder":"If the Mime was successful during the day, wake them and nod or shake your head, depending on whether the character is in play.","reminders":["...!"],"setup":false,"image":"https://menagerie.towerrangers.net/images/mimg.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/mime.png"}','published','the-menagerie/mime',datetime('now'),datetime('now'));